import numpy as np
from scipy import stats
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    if len(feats.ids) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check for correlation pairs to avoid near-duplicates
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                correlated_pairs.add((min(fid1,fid2), max(fid1,fid2)))

    # Calculate effect sizes using Welch's t-test
    effect_sizes = {}
    for i, fid in enumerate(feats.ids):
        group0 = feats.x[feats.y==0, i]
        group1 = feats.x[feats.y==1, i]
        if len(group0) > 0 and len(group1) > 0:
            t_stat, _ = stats.ttest_ind(group0, group1, equal_var=False)
            effect_sizes[fid] = abs(t_stat)

    # Sort by effect size
    sorted_features = sorted(effect_sizes.items(), key=lambda x: x[1], reverse=True)

    # Try to find drivers using stratified analysis
    drivers = []
    strata = list(set(feats.stratum))

    if len(strata) > 1:
        # For each feature, check if effect persists across strata
        for fid, _ in sorted_features[:5]:  # Check top 5 features
            effects = []
            for stratum in strata:
                mask = [s == stratum for s in feats.stratum]
                y_stratum = feats.y[mask]
                x_stratum = feats.x[mask, feats.column(fid)]

                if len(y_stratum) > 10 and sum(y_stratum) > 0 and sum(y_stratum) < len(y_stratum):
                    group0 = x_stratum[y_stratum==0]
                    group1 = x_stratum[y_stratum==1]
                    if len(group0) > 0 and len(group1) > 0:
                        t_stat, _ = stats.ttest_ind(group0, group1, equal_var=False)
                        effects.append(t_stat)

            if len(effects) >= len(strata) // 2 and all(abs(e) > 2.0 for e in effects):
                drivers.append(fid)
                if len(drivers) >= MAX_DRIVERS:
                    break

    # If we found drivers, include them in columns
    columns = tuple(drivers)

    # Add some strong features as columns even if not drivers
    if not drivers:
        strong_features = [fid for fid, effect in sorted_features if effect > 2.0][:3]
        columns = tuple(strong_features)

    # Build loadings (weighted score)
    loadings = {}
    if columns:
        # Use effect sizes as weights
        for fid in columns:
            loadings[fid] = effect_sizes.get(fid, 0.0)

        # Normalize weights
        total_weight = sum(loadings.values())
        if total_weight > 0:
            for fid in loadings:
                loadings[fid] /= total_weight

    # Include product terms for highly correlated pairs
    products = []
    for pair in list(correlated_pairs)[:2]:  # Limit to 2 product terms
        if pair[0] in feats.ids and pair[1] in feats.ids:
            products.append(pair)

    # Ensure we don't exceed term limits
    total_terms = len(columns) + len(products) + len(loadings)
    if total_terms > 12:
        # Reduce to minimal model
        columns = columns[:1]
        products = ()
        loadings = {k: v for k, v in list(loadings.items())[:1]}

    # Return design
    return Design(
        drivers=tuple(drivers),
        columns=columns,
        products=tuple(products),
        loadings=loadings
    )

